mapper.select:
		select count(*) from CHB_INVESTHOLD_INFO_SUB ciis
		/***三期CHB_SUBMIT_STATUS去除改造  20220310**/
		/*left join CHB_SUBMIT_STATUS status
    		on ciis.sumit_seq = status.seqno*/
		/***三期CHB_SUBMIT_STATUS去除改造  20220310**/


				to_char(ciis.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') >= #{submitDeadLineStart,jdbcType=VARCHAR}


				and to_char(ciis.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') <= #{submitDeadLineEnd,jdbcType=VARCHAR}



				#{item,jdbcType=VARCHAR}




				#{item,jdbcType=VARCHAR}



				and to_char(ciis.UPDATE_TIME,'yyyy-MM-dd') >= #{updateTimeStart,jdbcType=VARCHAR}


				and to_char(ciis.UPDATE_TIME,'yyyy-MM-dd') <= #{updateTimeEnd,jdbcType=VARCHAR}


				and to_char(ciis.SUBMIT_TIME,'yyyy-MM-dd') >= #{submitDateStart,jdbcType=VARCHAR}


				and to_char(ciis.SUBMIT_TIME,'yyyy-MM-dd') <= #{submitDateEnd,jdbcType=VARCHAR}


				/***三期CHB_SUBMIT_STATUS去除改造  20220310**/

             		#{submitFeedbackStatus,jdbcType=VARCHAR}

				/***三期CHB_SUBMIT_STATUS去除改造  20220310**/


				and ciis.REGIST_BANK_CODE like concat(concat('%',#{registBankCode,jdbcType=VARCHAR}),'%')




                #{item,jdbcType=VARCHAR}



			    and ciis.INDENTIFY_MARK like concat(concat('%',#{indentifyMark,jdbcType=VARCHAR}),'%')


				and ciis.HOLD_DATE >= to_date(#{holdDateStart,jdbcType=VARCHAR},'yyyy-MM-dd')


				and ciis.HOLD_DATE <= to_date(#{holdDateEnd,jdbcType=VARCHAR},'yyyy-MM-dd')



				#{item,jdbcType=VARCHAR}




		 	 		ciis.PRD_REGIST_CODE = #{investDto.prdRegistCode,jdbcType=VARCHAR} 
			 	 	and ciis.REGIST_BANK_CODE = #{investDto.registBankCode,jdbcType=VARCHAR} 
		 	 		and ciis.INDENTIFY_MARK = #{investDto.indentifyMark,jdbcType=VARCHAR}
		 	 		and ciis.CCY = #{investDto.ccy,jdbcType=VARCHAR}
		 	 		and to_char(ciis.HOLD_DATE,'yyyy-MM-dd') = to_char(#{investDto.holdDate,jdbcType=DATE},'yyyy-MM-dd')


			 	 			and ciis.SEND_STATUS in('02','03')


			 	 			and ciis.SEND_STATUS = #{investDto.sendStatus,jdbcType=VARCHAR}

		SELECT
		*
	FROM
    (
        SELECT
            tmp_page.*,
            ROWNUM row_id
        FROM (
				select 
			        ciis.REGIST_SEQNO           registSeqno,      
					ciis.REGIST_BANK_CODE       registBankCode,  
					ciis.CHB_SUBMIT_DEADLINE    chbSubmitDeadline,
					ciis.PRD_REGIST_CODE        prdRegistCode,    
					ciis.INDENTIFY_MARK         indentifyMark,    
					ciis.CCY                    ccy,              
					ciis.HOLD_DATE              holdDate,         
					ciis.AMOUNT                 amount,    
					decode(substr(ciis.AMOUNT,1,1),'.',0||ciis.AMOUNT,ciis.AMOUNT)                 amountExportExcel,      
					ciis.QTY                    qty,  
					decode(substr(ciis.QTY,1,1),'.',0||ciis.QTY,ciis.QTY)                    qtyExportExcel,            
					ciis.CNY_AMT                cnyAmt,         
					decode(substr(ciis.CNY_AMT,1,1),'.',0||ciis.CNY_AMT,ciis.CNY_AMT)                cnyAmtExportExcel,  
					ciis.REMARK                 remark,           
					ciis.SUBMIT_DEADLINE        submitDeadline,   
					ciis.WORKFLOW_ID            workflowId,       
					ciis.SEND_STATUS            sendStatus,       
					ciis.STATUS_DATE            statusDate,      
					ciis.STATUS                 status,           
					ciis.CREATE_USER            createUser,       
					ciis.CREATE_TIME            createTime,       
					ciis.UPDATE_USER            updateUser,       
					ciis.UPDATE_TIME            updateTime,         
					ciis.ORG_CODE               orgCode,          
					ciis.DEPT_CODE              deptCode,         
					ciis.SUBMIT_TIME            submitTime,
					ciis.SUMIT_SEQ				sumitSeq,
					ciis.CHECK_SEQNO			checkSeqno,
					crc.IS_LOGIC_CHECK			isLogicCheck,
					/***三期CHB_SUBMIT_STATUS去除改造  20220310**/
					ciis.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus,
					/***三期CHB_SUBMIT_STATUS去除改造  20220310**/
		ciis.SUBMIT_SEND_STATUS    submitSendStatus
			from CHB_INVESTHOLD_INFO_SUB ciis
		/***三期CHB_SUBMIT_STATUS去除改造  20220310**/
		/*left join CHB_SUBMIT_STATUS status
	    	on ciis.sumit_seq = status.seqno*/
		/***三期CHB_SUBMIT_STATUS去除改造  20220310**/
		left join CHB_REPORT_CHECK crc
	    	on ciis.CHECK_SEQNO = crc.CHECK_SEQNO


				to_char(ciis.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') >= #{submitDeadLineStart,jdbcType=VARCHAR}


				and to_char(ciis.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') <= #{submitDeadLineEnd,jdbcType=VARCHAR}



					#{item,jdbcType=VARCHAR}




					#{item,jdbcType=VARCHAR}





				and to_char(ciis.STATUS_DATE,'yyyy-MM-dd') >= #{updateTimeStart,jdbcType=VARCHAR}


				and to_char(ciis.STATUS_DATE,'yyyy-MM-dd') <= #{updateTimeEnd,jdbcType=VARCHAR}


				and to_char(ciis.SUBMIT_TIME,'yyyy-MM-dd') >= #{submitDateStart,jdbcType=VARCHAR}


				and to_char(ciis.SUBMIT_TIME,'yyyy-MM-dd') <= #{submitDateEnd,jdbcType=VARCHAR}


				/***三期CHB_SUBMIT_STATUS去除改造  20220310**/

					#{submitFeedbackStatus,jdbcType=VARCHAR}

				/***三期CHB_SUBMIT_STATUS去除改造  20220310**/


				and ciis.REGIST_BANK_CODE like concat(concat('%',#{registBankCode,jdbcType=VARCHAR}),'%')



					#{item,jdbcType=VARCHAR}




					#{item,jdbcType=VARCHAR}



				and ciis.hold_date >=to_date(#{holdDateStart,jdbcType=VARCHAR},'yyyy-MM-dd')


				and ciis.hold_date <=to_date(#{holdDateEnd,jdbcType=VARCHAR},'yyyy-MM-dd')


				and ciis.INDENTIFY_MARK like concat(concat('%',#{indentifyMark,jdbcType=VARCHAR}),'%')



					#{item,jdbcType=VARCHAR}



				and ciis.SEND_STATUS = #{sendStatus,jdbcType=VARCHAR}


				and ciis.REGIST_SEQNO = #{REGIST_SEQNO,jdbcType=VARCHAR}


		order by ciis.CHB_SUBMIT_DEADLINE,ciis.REGIST_SEQNO desc
        )tmp_page
		)
		WHERE
		row_id <= #{end}
		AND row_id > #{start}

